import * as T from './vendor/three.module.js';
const $=id=>document.getElementById(id);
const types=[
{name:'Red dwarf',color:'#ff9a65',class:'LOW-MASS MAIN-SEQUENCE STAR',temp:'Cooler',fuel:'Hydrogen fusion',example:'Proxima Centauri',desc:'Small stars with extraordinary staying power. Red dwarfs use their fuel slowly and can shine far longer than the present age of the universe.',facts:[['Small, but numerous','Red dwarfs are the most common stars in our galaxy.'],['A nearby neighbor','Proxima Centauri is a red dwarf just over four light-years away.'],['Patience on a cosmic scale','The lowest-mass red dwarfs can have predicted lifetimes of trillions of years.']]},
{name:'Sun-like star',color:'#fff1cd',class:'G-TYPE MAIN-SEQUENCE STAR',temp:'Intermediate',fuel:'Hydrogen fusion',example:'The Sun',desc:'Our Sun is a main-sequence star, steadily fusing hydrogen in its core. Gravity pulling inward is balanced by outward pressure in its hot interior.',facts:[['A star close to home','The Sun is the star that supplies Earth with light and warmth.'],['Not actually a yellow ball','Viewed from space, sunlight is essentially white. Its appearance changes through Earth’s atmosphere.'],['A long middle chapter','The Sun spends most of its lifetime in the main-sequence phase.']]},
{name:'Hot blue star',color:'#a6caff',class:'MASSIVE MAIN-SEQUENCE STAR',temp:'Hotter',fuel:'Rapid hydrogen fusion',example:'O / B spectral types',desc:'Brilliant blue stars have hotter surfaces than red stars. Massive stars use their fuel rapidly, so their lives can be much shorter than the Sun’s.',facts:[['Blue means hot','Stellar color provides a clue to surface temperature. Blue stars are hotter than red stars.'],['More fuel, shorter life','A massive star consumes fuel so quickly that its larger supply does not guarantee a longer lifetime.'],['Shaping their surroundings','Intense radiation and stellar winds can influence nearby clouds of gas.']]},
{name:'Red giant',color:'#ffbd80',class:'EVOLVED STAR',temp:'Cooler surface',fuel:'Evolved burning stages',example:'A future stage of the Sun',desc:'When a Sun-like star exhausts hydrogen in its core, its outer layers expand. A red giant can have a cooler surface while radiating much more energy overall.',facts:[['Big is not the same as hot','A large surface area can make a cool star extremely luminous.'],['A changing interior','As a star evolves, fusion shifts between different fuels and regions.'],['The Sun’s distant future','The Sun will eventually expand into a red giant, then shed its outer layers.']]},
{name:'White dwarf',color:'#e5eeff',class:'COMPACT STELLAR REMNANT',temp:'Varies as it cools',fuel:'Residual heat',example:'A Sun-like star’s remnant',desc:'A white dwarf is the dense exposed core left after a Sun-like star sheds its outer layers. It glows from stored heat and gradually cools.',facts:[['Small and dense','A typical white dwarf is roughly Earth-sized, despite containing a substantial fraction of a star’s mass.'],['A remnant, not a young star','Despite “dwarf” in its name, it is not the same type of object as a red dwarf.'],['A fading ember','A lone white dwarf no longer sustains the core fusion that powered its earlier life.']]}
];
const paths={sun:[['Stellar nursery','Gravity gathers gas and dust into a collapsing region.'],['Protostar','The growing object heats up as material falls inward.'],['Main sequence','Core hydrogen fusion powers a long, relatively stable chapter.'],['Red giant','The star expands as its internal fuel supply and structure change.'],['Planetary nebula','Outer layers drift into space. Despite the name, this is not a planet.'],['White dwarf','The exposed core slowly cools. The Sun will not become a black hole.']],massive:[['Stellar nursery','A dense part of a gas cloud collapses under gravity.'],['Massive protostar','Accretion builds a hot, high-mass young star.'],['Main sequence','Rapid hydrogen fusion produces intense energy output.'],['Evolved massive star','The star changes size and burns progressively heavier fuels. Its path depends on mass and other factors.'],['Core collapse','Many massive stars end in a core-collapse supernova; some collapse with little visible explosion.'],['Compact remnant','A neutron star or black hole may remain. The outcome depends on the core and the star’s history.']]};
let renderer,scene,camera,surface,halo,group,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,zoom=5.6;
function select(i){const d=types[i];$('star-name').textContent=d.name;$('star-class').textContent=d.class;$('star-description').textContent=d.desc;$('star-stats').innerHTML=[['SURFACE',d.temp],['ENERGY',d.fuel],['CONTEXT',d.example]].map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('');$('star-facts').innerHTML=d.facts.map(([h,t],n)=>`<article><span>0${n+1} / DID YOU KNOW?</span><h3>${h}</h3><p>${t}</p></article>`).join('');document.querySelectorAll('.star-choice').forEach((b,n)=>{b.classList.toggle('selected',n===i);b.setAttribute('aria-pressed',String(n===i))});if(surface){surface.material.uniforms.tint.value.set(d.color);halo.material.color.set(d.color);surface.scale.setScalar(i===4?.75:i===3?1.15:1);halo.scale.setScalar(i===4?3.5:i===3?5.4:4.7)}}
types.forEach((d,i)=>{const b=document.createElement('button');b.className='star-choice';b.innerHTML=`<i style="--star:${d.color}"></i><span>${d.name}</span>`;b.onclick=()=>select(i);$('star-options').append(b)});
function path(kind){document.querySelectorAll('[data-path]').forEach(b=>{b.classList.toggle('selected',b.dataset.path===kind);b.setAttribute('aria-pressed',String(b.dataset.path===kind))});$('life-stages').innerHTML=paths[kind].map(([h,t],i)=>`<li><span>0${i+1}</span><div><h3>${h}</h3><p>${t}</p></div></li>`).join('')};document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>path(b.dataset.path));path('sun');
try{const el=$('star-viewport');renderer=new T.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));el.append(renderer.domElement);scene=new T.Scene();camera=new T.PerspectiveCamera(38,1,.1,100);camera.position.z=zoom;group=new T.Group();scene.add(group);surface=new T.Mesh(new T.SphereGeometry(1.25,80,60),new T.ShaderMaterial({uniforms:{tint:{value:new T.Color('#fff1cd')}},vertexShader:'varying vec3 p; varying vec3 n; varying vec3 v; void main(){p=position;n=normalize(normalMatrix*normal);vec4 mv=modelViewMatrix*vec4(position,1.0);v=normalize(-mv.xyz);gl_Position=projectionMatrix*mv;}',fragmentShader:'uniform vec3 tint; varying vec3 p; varying vec3 n; varying vec3 v; void main(){float grain=sin(p.x*52.0+sin(p.y*31.0))*sin(p.y*64.0+cos(p.z*28.0))*sin(p.z*48.0+sin(p.x*35.0));float broad=sin(p.x*8.0+sin(p.z*6.0))*cos(p.y*11.0);float limb=pow(max(dot(normalize(n),normalize(v)),0.0),0.28);float light=(0.84+grain*0.09+broad*0.05)*(0.55+0.45*limb);gl_FragColor=vec4(tint*light,1.0);}'}));group.add(surface);const c=document.createElement('canvas');c.width=c.height=256;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(128,128,45,128,128,128);g.addColorStop(0,'rgba(255,255,255,.3)');g.addColorStop(.5,'rgba(255,255,255,.08)');g.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,256,256);halo=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),transparent:true,depthWrite:false,blending:T.AdditiveBlending}));scene.add(halo);const points=[];for(let i=0;i<500;i++)points.push((Math.random()-.5)*25,(Math.random()-.5)*16,-4-Math.random()*10);const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(points,3));scene.add(new T.Points(geometry,new T.PointsMaterial({color:0xa4bad0,size:.02})));new ResizeObserver(()=>{renderer.setSize(el.clientWidth,el.clientHeight);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix()}).observe(el);let drag=false,x=0,y=0;el.onpointerdown=e=>{drag=true;x=e.clientX;y=e.clientY;el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!drag)return;group.rotation.y+=(e.clientX-x)*.008;group.rotation.x+=(e.clientY-y)*.008;x=e.clientX;y=e.clientY};el.onpointerup=el.onpointercancel=()=>drag=false;el.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(4.3,Math.min(8,zoom+e.deltaY*.004))},{passive:false});let prev=0;renderer.setAnimationLoop(t=>{const dt=Math.min((t-prev)/1000,.05);prev=t;if(!paused&&!drag)group.rotation.y+=dt*.1;camera.position.z+=(zoom-camera.position.z)*.1;renderer.render(scene,camera)});$('star-fallback').hidden=true}catch(e){$('star-fallback').textContent='3D is unavailable in this browser. The star facts and life-cycle guide are still available.';$('star-controls').hidden=true}
function pauseLabel(){$('star-pause').textContent=paused?'▷ Resume':'Ⅱ Pause';$('star-pause').setAttribute('aria-pressed',String(paused))}pauseLabel();$('star-pause').onclick=()=>{paused=!paused;pauseLabel()};$('star-in').onclick=()=>zoom=Math.max(4.3,zoom-.5);$('star-out').onclick=()=>zoom=Math.min(8,zoom+.5);$('star-reset').onclick=()=>{zoom=5.6;group?.rotation.set(0,0,0)};select(1);
